// Tab 1: Viktos Zerodarker Jacket
await tool.navigate({ tabId: 2017691829, url: "https://viktos.com/zerodarker-jacket/" });

// Tab 2: 5.11 Return Policy (already at https://www.511tactical.com/customer-service/return-policy)

// Tab 3: Helikon-Tex Level 7 Jacket
await tool.navigate({ tabId: 2017692039, url: "https://helikon-tex.com/en/catalog/product/view/id/51699/s/level-7-jacket-nylonen/category/696/" });

// Tab 4: Carinthia HIG 4.0 Jacket
await tool.navigate({ tabId: 2017692040, url: "https://www.carinthia.eu/en/hig-4-0-jacket-p1967/" });

// Tab 5: UF PRO Delta OL 4.0 Tactical Winter Jacket
await tool.navigate({ tabId: 2017692041, url: "https://ufpro.com/us/p/delta-ol-4-tactical-winter-jacket-brown-grey" });

// Tab 6: Viktos Size Guide
await tool.navigate({ tabId: 2017692042, url: "https://viktos.com/size-guide/" });

// Wait for all to load
await Promise.all([
  tool.wait_for({ tabId: 2017691829, condition: "load_state", value: "load" }),
